// revenue-conversion-fix.js
// Ensures paidEvents increment when checkout completes successfully.
// Hook into checkout success flow.

const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function recordPaidEvent(amount, currency = 'USD') {
  try {
    let data = { paidEvents: 0, totalRevenue: 0, currency };
    if (fs.existsSync(REVENUE_FILE)) {
      const raw = fs.readFileSync(REVENUE_FILE, 'utf8');
      data = JSON.parse(raw);
    }
    data.paidEvents = (data.paidEvents || 0) + 1;
    data.totalRevenue = (data.totalRevenue || 0) + amount;
    data.lastPaidAt = new Date().toISOString();
    fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
    console.log(`[RevenueFix] Recorded paid event: +${amount} ${currency}`);
    return true;
  } catch (err) {
    console.error('[RevenueFix] Error recording paid event:', err);
    return false;
  }
}

// Expose for integration with checkout success handler
module.exports = { recordPaidEvent };
